def parse_docstring(docstring: Optional[str]) -> Dict[str, str]:
    """Parses a docstring into summary and description."""
    if not docstring:
        return {"summary": "No summary available.", "description": ""}

    lines = docstring.strip().split("\n")
    summary = lines[0].strip()
    description = "\n".join(lines[1:]).strip() if len(lines) > 1 else ""

    return {"summary": summary, "description": description}

def generate_openapi_spec(app: Flask, view_func: Callable) -> Dict[str, Any]:
    """
    Generates an OpenAPI 3.0 operation object for a specific Flask view function.

    Args:
        app: The Flask application instance.
        view_func: The view function to document.

    Returns:
        A dictionary representing the OpenAPI specification for this route.

    Raises:
        ValueError: If the view function is not registered with the Flask app.
    """
    try:
        # 1. Identify the endpoint and rule
        endpoint = None
        for ep, func in app.view_functions.items():
            if func == view_func:
                endpoint = ep
                break

        if not endpoint:
            raise ValueError(f"Function {view_func.__name__} is not a registered view in the provided Flask app.")

        # Find the URL rule associated with this endpoint
        # Note: A view can have multiple rules; we take the first one for simplicity here.
        rule: Optional[Rule] = next((r for r in app.url_map.iter_rules() if r.endpoint == endpoint), None)

        if not rule:
            raise ValueError(f"No URL rule found for endpoint: {endpoint}")

        # 2. Basic Metadata
        doc_info = parse_docstring(view_func.__doc__)
        spec = {
            "summary": doc_info["summary"],
            "description": doc_info["description"],
            "operationId": view_func.__name__,
            "parameters": [],
            "responses": {
                "200": {
                    "description": "Successful Response"
                }
            }
        }

        # 3. Inspect Function Signature for Parameters
        sig = inspect.signature(view_func)
        path_params = list(rule.arguments) # Arguments defined in the URL rule (e.g., <int:user_id>)

        for name, param in sig.parameters.items():
            # Skip 'self' or 'cls' if it's a method view
            if name in ['self', 'cls']:
                continue

            # Determine location (path vs query)
            # If the argument is in the URL rule, it's a 'path' param, otherwise 'query'
            location = "path" if name in path_params else "query"

            # Extract Type info
            param_type = "string" # Default
            if param.annotation != inspect.Parameter.empty:
                param_type = get_openapi_type(param.annotation)

            # Build Parameter Object
            parameter_obj = {
                "name": name,
                "in": location,
                "required": location == "path" or param.default == inspect.Parameter.empty,
                "schema": {
                    "type": param_type
                }
            }
            spec["parameters"].append(parameter_obj)

        # 4. Determine HTTP Methods
        # Flask rules store methods as a Set. We exclude HEAD and OPTIONS usually.
        methods = rule.methods - {'HEAD', 'OPTIONS'} if rule.methods else {'GET'}

        # Structure the final output keyed by Method and Path
        # OpenAPI structure: paths -> /url -> method -> spec
        full_spec = {
            "path": rule.rule,
            "methods": {method.lower(): spec for method in methods}
        }

