    except Exception as e:
        # Fallback error handling to ensure application doesn't crash during doc generation
        print(f"Error generating OpenAPI for {view_func.__name__}: {str(e)}")
        return {
            "error": f"Failed to generate documentation: {str(e)}"
        }

# ==========================================
# Example Usage
# ==========================================

if __name__ == "__main__":
    import json

    # 1. Setup a simple Flask App
